ALTER TABLE public.alarms ADD COLUMN IF NOT EXISTS wake_repeat_daily boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS wake_difficulty smallint NOT NULL DEFAULT 2, ADD COLUMN IF NOT EXISTS wake_next_fire_at timestamptz, ADD COLUMN IF NOT EXISTS wake_saved_at timestamptz, ADD COLUMN IF NOT EXISTS wake_timezone text;
ALTER TABLE public.quiz_questions ADD COLUMN IF NOT EXISTS wake_only boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS fact_source text;
ALTER POLICY "Signed in users can read active questions" ON public.quiz_questions USING (is_active AND NOT wake_only);
CREATE TABLE public.alarm_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,alarm_id uuid NOT NULL REFERENCES public.alarms(id),scheduled_for timestamptz NOT NULL,local_date date NOT NULL,timezone text NOT NULL,wake_time time NOT NULL,saved_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'scheduled',question_id uuid,question_text text,question_options jsonb,question_answer text,question_explanation text,question_hash text,question_version integer NOT NULL DEFAULT 0,question_type text NOT NULL,difficulty smallint NOT NULL DEFAULT 2,correct_in_row integer NOT NULL DEFAULT 0,question_cycle integer NOT NULL DEFAULT 0,tier integer NOT NULL DEFAULT 0,coins_awarded integer NOT NULL DEFAULT 0,first_ring_at timestamptz,solved_at timestamptz,last_answer_at timestamptz,is_test boolean NOT NULL DEFAULT false,reward_result text,push_round integer NOT NULL DEFAULT 0,next_push_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT alarm_event_status CHECK(status IN ('scheduled','ringing','solved','expired')),UNIQUE(alarm_id,scheduled_for,is_test));
GRANT ALL ON public.alarm_events TO service_role;
ALTER TABLE public.alarm_events ENABLE ROW LEVEL SECURITY;
CREATE INDEX alarm_events_status_schedule ON public.alarm_events(status,scheduled_for);
CREATE INDEX alarm_events_scheduled_due ON public.alarm_events(scheduled_for) WHERE status='scheduled';
CREATE INDEX alarm_events_user_ringing ON public.alarm_events(user_id,status);
CREATE INDEX alarm_events_push_due ON public.alarm_events(next_push_at) WHERE status='ringing' AND push_round<30;
CREATE TABLE public.wake_question_history (user_id uuid NOT NULL,question_hash text NOT NULL,question_type text NOT NULL,cycle integer NOT NULL DEFAULT 0,issued_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,question_type,cycle,question_hash));
GRANT ALL ON public.wake_question_history TO service_role;
ALTER TABLE public.wake_question_history ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.wake_push_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,endpoint text NOT NULL UNIQUE,p256dh text NOT NULL,auth_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.wake_push_subscriptions TO service_role;
ALTER TABLE public.wake_push_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE INDEX wake_push_user ON public.wake_push_subscriptions(user_id);
CREATE TABLE public.wake_push_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES public.alarm_events(id),subscription_id uuid NOT NULL REFERENCES public.wake_push_subscriptions(id) ON DELETE CASCADE,round integer NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,retry_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,accepted_at timestamptz,last_error text,UNIQUE(event_id,subscription_id,round));
GRANT ALL ON public.wake_push_outbox TO service_role;
ALTER TABLE public.wake_push_outbox ENABLE ROW LEVEL SECURITY;
CREATE INDEX wake_outbox_retry ON public.wake_push_outbox(retry_at,lease_until) WHERE status IN ('pending','leased');
CREATE TABLE public.wake_delivery_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_id uuid,kind text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),detail text);
GRANT ALL ON public.wake_delivery_log TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.wake_delivery_log_id_seq TO service_role;
ALTER TABLE public.wake_delivery_log ENABLE ROW LEVEL SECURITY;
CREATE INDEX wake_delivery_day ON public.wake_delivery_log(occurred_at,kind);
CREATE OR REPLACE FUNCTION public.wake_tier_coins(t time) RETURNS integer LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT CASE WHEN t>='04:00' AND t<'05:00' THEN 10 WHEN t<'06:00' AND t>='05:00' THEN 7 WHEN t<'07:00' AND t>='06:00' THEN 5 WHEN t<'08:00' AND t>='07:00' THEN 3 ELSE 0 END; $$;
CREATE OR REPLACE FUNCTION public.wake_next_fire(t time,z text,at_time timestamptz DEFAULT now()) RETURNS timestamptz LANGUAGE plpgsql STABLE SET search_path='' AS $$ DECLARE day date:=(at_time AT TIME ZONE z)::date; candidate timestamptz; exact timestamptz; after_gap timestamptz; i integer; BEGIN IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=z) THEN RAISE EXCEPTION 'invalid timezone'; END IF; FOR i IN 0..2 LOOP SELECT min(s) FILTER(WHERE (s AT TIME ZONE z)=(day+i)+t),min(s) FILTER(WHERE (s AT TIME ZONE z)::date=day+i AND (s AT TIME ZONE z)::time>=t) INTO exact,after_gap FROM generate_series(((day+i)::timestamp AT TIME ZONE z)-interval '15 hours',((day+i+1)::timestamp AT TIME ZONE z)+interval '15 hours',interval '1 minute') s; candidate:=coalesce(exact,after_gap); IF candidate>at_time THEN RETURN candidate; END IF; END LOOP; RAISE EXCEPTION 'cannot schedule'; END; $$;
CREATE OR REPLACE FUNCTION public.wake_create_occurrence(aid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a public.alarms; eid uuid; BEGIN SELECT * INTO a FROM public.alarms WHERE id=aid FOR UPDATE; IF a.label<>'AXEN Wake Protocol' OR NOT a.is_active OR a.wake_next_fire_at IS NULL THEN RETURN NULL; END IF; INSERT INTO public.alarm_events(user_id,alarm_id,scheduled_for,local_date,timezone,wake_time,saved_at,question_type,difficulty,tier) VALUES(a.user_id,a.id,a.wake_next_fire_at,(a.wake_next_fire_at AT TIME ZONE a.wake_timezone)::date,a.wake_timezone,a.time,coalesce(a.wake_saved_at,now()),a.challenge_type,a.wake_difficulty,public.wake_tier_coins(a.time)) ON CONFLICT(alarm_id,scheduled_for,is_test) DO UPDATE SET question_type=EXCLUDED.question_type,difficulty=EXCLUDED.difficulty WHERE alarm_events.status='scheduled' RETURNING id INTO eid; RETURN eid; END; $$;
CREATE OR REPLACE FUNCTION public.wake_save_settings(_time time,_sleep time,_tone text,_mode text,_enabled boolean,_repeat boolean,_difficulty smallint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u uuid:=auth.uid(); a public.alarms; z text; at_time timestamptz; saved timestamptz; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='42501'; END IF; IF _mode NOT IN ('math','science') OR _difficulty NOT BETWEEN 1 AND 3 OR _tone NOT IN ('superloud','scariest','techno','meduzza','classic','morning','retro','emergency','modern','oppenheimer') THEN RAISE EXCEPTION 'invalid settings'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(u::text,74011)); IF EXISTS(SELECT 1 FROM public.alarm_events WHERE user_id=u AND status='ringing') THEN RAISE EXCEPTION 'Solve the ringing alarm before changing settings'; END IF; SELECT reward_timezone INTO z FROM public.profiles WHERE id=u; SELECT * INTO a FROM public.alarms WHERE user_id=u AND label='AXEN Wake Protocol' ORDER BY created_at LIMIT 1 FOR UPDATE; at_time:=CASE WHEN _enabled THEN public.wake_next_fire(_time,z) ELSE NULL END; saved:=CASE WHEN a.time=_time AND a.is_active=_enabled AND a.wake_repeat_daily=_repeat AND a.wake_timezone=z THEN coalesce(a.wake_saved_at,now()) ELSE now() END; IF a.id IS NULL THEN INSERT INTO public.alarms(user_id,time,label,tone,days,challenge_type,is_active,sleep_recommendation,recovery_enabled,wake_repeat_daily,wake_difficulty,wake_next_fire_at,wake_saved_at,wake_timezone) VALUES(u,_time,'AXEN Wake Protocol',_tone,'{0,1,2,3,4,5,6}',_mode,_enabled,_sleep,_enabled,_repeat,_difficulty,at_time,saved,z) RETURNING * INTO a; ELSE UPDATE public.alarms SET time=_time,tone=_tone,challenge_type=_mode,is_active=_enabled,sleep_recommendation=_sleep,recovery_enabled=_enabled,wake_repeat_daily=_repeat,wake_difficulty=_difficulty,wake_next_fire_at=at_time,wake_saved_at=saved,wake_timezone=z WHERE id=a.id RETURNING * INTO a; END IF; UPDATE public.alarm_events SET status='expired' WHERE alarm_id=a.id AND status='scheduled' AND NOT is_test AND (scheduled_for IS DISTINCT FROM at_time); IF _enabled THEN PERFORM public.wake_create_occurrence(a.id); END IF; RETURN jsonb_build_object('alarm_id',a.id,'server_now',now(),'next_fire_at',at_time,'timezone',z,'time',a.time,'sleep_time',a.sleep_recommendation,'enabled',a.is_active,'repeat_daily',a.wake_repeat_daily,'tone',a.tone,'mode',a.challenge_type,'difficulty',a.wake_difficulty); END; $$;
CREATE OR REPLACE FUNCTION public.wake_issue_question(eid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e public.alarm_events; q public.quiz_questions; cycle_no integer; hh text; aa integer; bb integer; cc integer; pick integer; txt text; ans text; explanation text; tries integer:=0; BEGIN SELECT * INTO e FROM public.alarm_events WHERE id=eid FOR UPDATE; SELECT coalesce(max(cycle),0) INTO cycle_no FROM public.wake_question_history WHERE user_id=e.user_id AND question_type=e.question_type; IF e.question_type='science' THEN SELECT * INTO q FROM public.quiz_questions x WHERE x.wake_only AND x.is_active AND x.subject<>'math' AND NOT EXISTS(SELECT 1 FROM public.wake_question_history h WHERE h.user_id=e.user_id AND h.question_type='science' AND h.cycle=cycle_no AND h.question_hash=md5(x.question_text)) ORDER BY md5(e.user_id::text||e.local_date::text||x.id::text||cycle_no::text) LIMIT 1; IF q.id IS NULL THEN cycle_no:=cycle_no+1; SELECT * INTO q FROM public.quiz_questions x WHERE x.wake_only AND x.is_active AND x.subject<>'math' ORDER BY md5(e.user_id::text||e.local_date::text||x.id::text||cycle_no::text) LIMIT 1; END IF; IF q.id IS NULL THEN RAISE EXCEPTION 'Science bank is not ready'; END IF; txt:=q.question_text; ans:=q.correct_answer; explanation:=q.explanation; hh:=md5(txt); ELSE LOOP tries:=tries+1; aa:=5+floor(random()*CASE e.difficulty WHEN 1 THEN 20 WHEN 2 THEN 80 ELSE 200 END)::integer; bb:=2+floor(random()*12)::integer; cc:=3+floor(random()*20)::integer; pick:=floor(random()*5)::integer; IF pick=0 THEN txt:=aa||' + '||bb||' = ?';ans:=(aa+bb)::text; ELSIF pick=1 THEN txt:='('||aa||' × '||bb||') − '||cc||' = ?';ans:=(aa*bb-cc)::text; ELSIF pick=2 THEN txt:=bb||'x + '||cc||' = '||(bb*aa+cc)||'. x = ?';ans:=aa::text; ELSIF pick=3 THEN txt:='What is '||(bb*5)||'% of '||(aa*20)||'?';ans:=(bb*aa)::text; ELSE txt:='Next number: '||aa||', '||(aa+bb)||', '||(aa+2*bb)||', '||(aa+3*bb)||', ?';ans:=(aa+4*bb)::text; END IF; hh:=md5(txt); EXIT WHEN NOT EXISTS(SELECT 1 FROM public.wake_question_history WHERE user_id=e.user_id AND question_type='math' AND question_hash=hh); IF tries>500 THEN RAISE EXCEPTION 'Could not issue a unique question'; END IF; END LOOP; explanation:='The correct result is '||ans||'.'; END IF; INSERT INTO public.wake_question_history(user_id,question_hash,question_type,cycle) VALUES(e.user_id,hh,e.question_type,cycle_no); UPDATE public.alarm_events SET question_id=coalesce(q.id,gen_random_uuid()),question_text=txt,question_options=CASE WHEN e.question_type='science' THEN q.options ELSE NULL END,question_answer=ans,question_explanation=explanation,question_hash=hh,question_version=question_version+1,question_cycle=cycle_no WHERE id=eid; END; $$;
CREATE OR REPLACE FUNCTION public.wake_event_payload(eid uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('id',e.id,'status',e.status,'scheduled_for',e.scheduled_for,'first_ring_at',e.first_ring_at,'local_date',e.local_date,'timezone',e.timezone,'time',e.wake_time,'tier',e.tier,'is_test',e.is_test,'tone',a.tone,'question',CASE WHEN e.status='ringing' THEN jsonb_build_object('id',e.question_id,'version',e.question_version,'text',e.question_text,'options',e.question_options,'type',e.question_type,'correct_in_row',e.correct_in_row) ELSE NULL END,'awarded',e.coins_awarded,'result',e.reward_result) FROM public.alarm_events e JOIN public.alarms a ON a.id=e.alarm_id WHERE e.id=eid; $$;
CREATE OR REPLACE FUNCTION public.wake_get_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u uuid:=auth.uid(); a public.alarms; e public.alarm_events; z text; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='42501'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(u::text,74011)); SELECT * INTO a FROM public.alarms WHERE user_id=u AND label='AXEN Wake Protocol' ORDER BY created_at LIMIT 1; SELECT reward_timezone INTO z FROM public.profiles WHERE id=u; SELECT * INTO e FROM public.alarm_events WHERE user_id=u AND status IN ('ringing','scheduled') AND (status='ringing' OR scheduled_for<=now()) ORDER BY CASE status WHEN 'ringing' THEN 0 ELSE 1 END,scheduled_for LIMIT 1 FOR UPDATE; IF e.id IS NOT NULL AND e.status='scheduled' THEN UPDATE public.alarm_events SET status='ringing',first_ring_at=now(),next_push_at=now() WHERE id=e.id; INSERT INTO public.wake_delivery_log(event_id,kind) VALUES(e.id,'ringing'); END IF; IF e.id IS NOT NULL AND e.question_id IS NULL THEN PERFORM public.wake_issue_question(e.id); END IF; RETURN jsonb_build_object('server_now',now(),'local_date',(now() AT TIME ZONE z)::date,'timezone',z,'settings',CASE WHEN a.id IS NOT NULL THEN jsonb_build_object('alarm_id',a.id,'time',a.time,'sleep_time',a.sleep_recommendation,'enabled',a.is_active,'repeat_daily',a.wake_repeat_daily,'tone',a.tone,'mode',a.challenge_type,'difficulty',a.wake_difficulty,'next_fire_at',a.wake_next_fire_at) ELSE NULL END,'event',public.wake_event_payload(e.id)); END; $$;
CREATE OR REPLACE FUNCTION public.wake_test_alarm() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u uuid:=auth.uid(); a public.alarms; eid uuid; z text; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='42501'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(u::text,74011)); SELECT id INTO eid FROM public.alarm_events WHERE user_id=u AND status='ringing' LIMIT 1; IF eid IS NOT NULL THEN RETURN eid; END IF; SELECT * INTO a FROM public.alarms WHERE user_id=u AND label='AXEN Wake Protocol' ORDER BY created_at LIMIT 1; IF a.id IS NULL THEN RAISE EXCEPTION 'Save protocol settings first'; END IF; SELECT reward_timezone INTO z FROM public.profiles WHERE id=u; SELECT id INTO eid FROM public.alarm_events WHERE user_id=u AND is_test AND status='scheduled' LIMIT 1; IF eid IS NOT NULL THEN RETURN eid; END IF; INSERT INTO public.alarm_events(user_id,alarm_id,scheduled_for,local_date,timezone,wake_time,saved_at,question_type,difficulty,tier,is_test) VALUES(u,a.id,now()+interval '10 seconds',(now() AT TIME ZONE z)::date,z,a.time,now(),a.challenge_type,a.wake_difficulty,0,true) RETURNING id INTO eid; RETURN eid; END; $$;
REVOKE ALL ON FUNCTION public.wake_create_occurrence(uuid),public.wake_issue_question(uuid),public.wake_event_payload(uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.wake_save_settings(time,time,text,text,boolean,boolean,smallint),public.wake_get_state(),public.wake_test_alarm() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.wake_save_settings(time,time,text,text,boolean,boolean,smallint),public.wake_get_state(),public.wake_test_alarm() TO authenticated,service_role;
COMMENT ON COLUMN public.alarms.wake_next_fire_at IS 'Server-authoritative UTC next occurrence for Wake Protocol; legacy local wake-plan scheduling is deprecated for this feature.';